var exec=require('cordova/exec');module.exports={capture:function(ok,fail){exec(ok,fail,'NearbyPhotos','capture',[]);},nearby:function(lat,lon,radius,ok,fail){exec(ok,fail,'NearbyPhotos','nearby',[lat,lon,radius]);},thumbnail:function(id,ok,fail){exec(ok,fail,'NearbyPhotos','thumbnail',[id]);},renameAlbum:function(oldName,newName,ok,fail){exec(ok,fail,'NearbyPhotos','renameAlbum',[oldName,newName]);},addToAlbum:function(title,ids,ok,fail){exec(ok,fail,'NearbyPhotos','addToAlbum',[title,ids]);},pick:function(ok,fail){exec(ok,fail,'NearbyPhotos','pick',[]);}};